package zkcircuit

import (
	"errors"
	"testing"
)

func TestScratchNameAmbiguity(t *testing.T) {
	dir := t.TempDir()
	s, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	for _, n := range []string{"a", "b"} {
		if _, err := s.CreateCircuit(Circuit{Name: n, Version: 1, Constraints: 1}); err != nil {
			t.Fatal(err)
		}
		if _, err := s.FreezeCircuit(n, 1); err != nil {
			t.Fatal(err)
		}
	}
	if _, err := s.RecordSetup("a", 1); err != nil {
		t.Fatal(err)
	}
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}

	// Plant "name":"a" and "NAME":"b" on the one setup record.
	raw, _ := readDataFile(t, dir)
	marker := `"setups": [`
	at := indexOf(string(raw), marker)
	old := `"name": "a"`
	rel := indexOf(string(raw)[at:], old)
	pos := at + rel
	frag := `"name": "a", "NAME": "b"`
	bad := string(raw[:pos]) + frag + string(raw[pos+len(old):])
	writeDataFile(t, dir, []byte(bad))

	if _, err := Open(dir); !errors.Is(err, ErrDataCorrupt) {
		t.Fatalf("want ErrDataCorrupt, got %v", err)
	} else {
		t.Logf("error: %v", err)
	}
}

func indexOf(s, sub string) int {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return i
		}
	}
	return -1
}
EOF
go test ./zkcircuit/ -run TestScratchNameAmbiguity -v 2>&1 | tail -8

